import os
import requests
import streamlit as st

# Streamlit Page Configuration
st.set_page_config(
    page_title="Diabetes Risk Prediction - ML System",
    page_icon="🩺",
    layout="centered",
)

# Fetch Backend API URL from environment variable or default to local/compose
API_URL = os.getenv("API_URL", "http://api:8000/predict")

st.title("🩺 Diabetes Risk Prediction")
st.markdown(
    "Enter the patient's medical parameters below to receive an instant risk assessment "
    "generated by a containerized machine learning model."
)

st.divider()

# Input Form
with st.form(key="patient_form"):
    st.subheader("📋 Patient Medical Data")

    col1, col2 = st.columns(2)

    with col1:
        pregnancies = st.number_input(
            "Pregnancies", min_value=0, max_value=20, value=1, step=1
        )
        glucose = st.number_input(
            "Glucose Level (mg/dL)",
            min_value=0,
            max_value=300,
            value=120,
            step=1,
        )
        blood_pressure = st.number_input(
            "Blood Pressure (mmHg)",
            min_value=0,
            max_value=200,
            value=70,
            step=1,
        )
        skin_thickness = st.number_input(
            "Skin Thickness (mm)", min_value=0, max_value=100, value=20, step=1
        )

    with col2:
        insulin = st.number_input(
            "Insulin Level (µU/ml)",
            min_value=0,
            max_value=900,
            value=80,
            step=1,
        )
        bmi = st.number_input(
            "Body Mass Index (BMI)",
            min_value=0.0,
            max_value=70.0,
            value=25.4,
            step=0.1,
        )
        diabetes_pedigree = st.number_input(
            "Diabetes Pedigree Function",
            min_value=0.0,
            max_value=3.0,
            value=0.47,
            step=0.01,
        )
        age = st.number_input(
            "Age (years)", min_value=1, max_value=120, value=33, step=1
        )

    submit_button = st.form_submit_button(
        label="🔍 Analyze Patient Data", use_container_width=True
    )

if submit_button:
    payload = {
        "pregnancies": int(pregnancies),
        "glucose": float(glucose),
        "blood_pressure": float(blood_pressure),
        "skin_thickness": float(skin_thickness),
        "insulin": float(insulin),
        "bmi": float(bmi),
        "diabetes_pedigree": float(diabetes_pedigree),
        "age": int(age),
    }

    with st.spinner(
        "Sending data to API microservice and running ML inference..."
    ):
        try:
            response = requests.post(API_URL, json=payload, timeout=10)

            if response.status_code == 200:
                result = response.json()
                prediction = result.get("prediction")
                probability = result.get("probability", 0.0)

                st.divider()
                st.subheader("📊 Analysis Results")

                prob_pct = probability * 100

                if prediction == 1:
                    st.error(
                        f"⚠️ **HIGH DIABETES RISK** (Probability: {prob_pct:.1f}%)"
                    )
                    st.progress(probability)
                    st.warning(
                        "Medical consultation and further diagnostic evaluation recommended."
                    )
                else:
                    st.success(
                        f"✅ **LOW DIABETES RISK** (Probability: {prob_pct:.1f}%)"
                    )
                    st.progress(probability)
                    st.info(
                        "Results are within normal parameters. Routine preventative care recommended."
                    )
            else:
                st.error(f"API Error ({response.status_code}): {response.text}")

        except requests.exceptions.ConnectionError:
            st.error(
                f"Could not connect to API at `{API_URL}`. Please verify that the backend container is running."
            )
        except Exception as e:
            st.error(f"An unexpected error occurred: {e}")
